import{_ as o,a0 as r,w as p,s as l,I as e,x as a,a1 as s,A as i,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"用 Portainer.io 来监控和管理 Docker 容器（2） | LCTT x X-CMD","titleTemplate":false,"description":"用 Portainer.io 来监控和管理 Docker 容器（2） | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Portainer.io 来监控和管理 Docker 容器（2） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Portainer.io 来监控和管理 Docker 容器（2） | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20190516 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-2","title":"用 Portainer.io 来监控和管理 Docker 容器（2）","tag":"202101","desc":""},"relativePath":"202101/20190516 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-2.md","filePath":"[post].md"}'),d={name:"202101/20190516 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-2.md"};function h(u,t,g,m,w,x){const n=r("Link");return p(),l("div",null,[t[18]||(t[18]=e("h1",{id:"用-portainer-io-来监控和管理-docker-容器-2",tabindex:"-1"},[a("用 Portainer.io 来监控和管理 Docker 容器（2） "),e("a",{class:"header-anchor",href:"#用-portainer-io-来监控和管理-docker-容器-2","aria-label":"Permalink to “用 Portainer.io 来监控和管理 Docker 容器（2）”"},"​")],-1)),t[19]||(t[19]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202101/14/204401knuxjru53n5su6ns.jpg",alt:""})],-1)),e("p",null,[t[1]||(t[1]=a("作为",-1)),s(n,{href:"https://linux.cn/article-12634-1.html"},{default:i(()=>[...t[0]||(t[0]=[a("第 1 部分",-1)])]),_:1}),t[2]||(t[2]=a("的延续，本第 2 部分将介绍 Portainer 的其余功能。",-1))]),t[20]||(t[20]=c(`<h3 id="监控-docker-容器镜像" tabindex="-1">监控 docker 容器镜像 <a class="header-anchor" href="#监控-docker-容器镜像" aria-label="Permalink to “监控 docker 容器镜像”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~}$ docker ps -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE                 COMMAND             CREATED             STATUS   PORTS                             NAMES</span></span>
<span class="line"><span>9ab9aa72f015        ubuntu                &quot;/bin/bash&quot;         14 seconds ago      Exited (0) 12 seconds ago                  suspicious_shannon</span></span>
<span class="line"><span>305369d3b2bb        centos                &quot;/bin/bash&quot;         24 seconds ago      Exited (0) 22 seconds ago                  admiring_mestorf</span></span>
<span class="line"><span>9a669f3dc4f6        portainer/portainer   &quot;/portainer&quot;        7 minutes ago       Up 7 minutes   0.0.0.0:9000-&gt;9000/tcp      trusting_keller</span></span></code></pre></div><p>包括 <code>portainer</code>（docker 容器镜像），所有已退出和当前正在运行的 docker 镜像都会显示出来。下面的 Portainer GUI 屏幕截图显示了相同的情况。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Docker_status-1024x423.jpg" alt="Docker_status"></p><h3 id="监视事件" tabindex="-1">监视事件 <a class="header-anchor" href="#监视事件" aria-label="Permalink to “监视事件”">​</a></h3><p>单击 portainer 网页中的“Events”选项，如下所示。</p><p>基于 docker 容器活动生成和创建的各种事件将被提取并显示在此页面中.</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Events-1024x404.jpg" alt="Container-Events-Poratiner-GUI"></p><p>现在检查并验证“Events”部分是如何工作的。创建一个新的 docker 容器镜像 <code>redis</code>，如下所述，在 docker 命令行检查状态：<code>docker ps –a</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~}$ docker ps -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE                 COMMAND                  CREATED              STATUS         PORTS                    NAMES</span></span>
<span class="line"><span>cdbfbef59c31        redis                 &quot;docker-entrypoint.s…&quot;   About a minute ago   Up About a minute         6379/tcp                 angry_varahamihira</span></span>
<span class="line"><span>9ab9aa72f015        ubuntu                &quot;/bin/bash&quot;              10 minutes ago       Exited (0) 10 minutes ago                            suspicious_shannon</span></span>
<span class="line"><span>305369d3b2bb        centos                &quot;/bin/bash&quot;              11 minutes ago       Exited (0) 11 minutes ago                            admiring_mestorf</span></span>
<span class="line"><span>9a669f3dc4f6        portainer/portainer   &quot;/portainer&quot;             17 minutes ago       Up 17 minutes         0.0.0.0:9000-&gt;9000/tcp   trusting_keller</span></span></code></pre></div><p>单击顶部的“Event List”刷新事件列表，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/events_updated-1024x414.jpg" alt="events_updated"></p><p>现在事件的页面也更新了这个变化，</p><h3 id="主机状态" tabindex="-1">主机状态 <a class="header-anchor" href="#主机状态" aria-label="Permalink to “主机状态”">​</a></h3><p>下面是 portainer 显示主机状态的屏幕截图。这是一个简单的窗口。这显示了主机 Linux 机器的基本信息，如“CPU”、“主机名”、“操作系统信息”等。这个页面在不需要登录主机命令行的情况下提供了非常有用的信息，以便快速浏览。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Host_names-1024x408.jpg" alt="Host-names-Portainer"></p><h3 id="portainer-中的仪表板" tabindex="-1">Portainer 中的仪表板 <a class="header-anchor" href="#portainer-中的仪表板" aria-label="Permalink to “Portainer 中的仪表板”">​</a></h3><p>到目前为止，我们已经在“Local”部分看到了基于 portainer 的各种特性。现在跳到所选 Docker 容器镜像的“Dashboard”部分。</p><p>在 Portainer 的网页中单击“EndPoint”选项时，会出现以下窗口：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/End_Point_Settings-1024x471.jpg" alt="End_Point_Settings"></p><p>对于主机容器镜像，此仪表板有许多状态和选项。</p><h4 id="stacks" tabindex="-1">Stacks <a class="header-anchor" href="#stacks" aria-label="Permalink to “Stacks”">​</a></h4><p>单击此选项可提供任何堆栈（如果有的话）的状态。因为这里没有堆栈，所以显示为零。</p><h4 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to “Images”">​</a></h4><p>单击此选项可提供主机中可用的容器镜像。此选项将显示所有活动和退出的容器镜像。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Images-1024x398.jpg" alt="Docker-Container-Images-Portainer"></p><p>例如，再创建一个“Nginx”容器并刷新此列表以查看更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~}$  sudo docker run nginx</span></span>
<span class="line"><span>Unable to find image &#39;nginx:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from library/nginx</span></span>
<span class="line"><span>27833a3ba0a5: Pull complete</span></span>
<span class="line"><span>ea005e36e544: Pull complete</span></span>
<span class="line"><span>d172c7f0578d: Pull complete</span></span>
<span class="line"><span>Digest: sha256:e71b1bf4281f25533cf15e6e5f9be4dac74d2328152edf7ecde23abc54e16c1c</span></span>
<span class="line"><span>Status: Downloaded newer image for nginx:latest</span></span></code></pre></div><p>下面是刷新后的镜像界面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Nginx_Image_creation-1024x439.jpg" alt="Nginx_Image_creation"></p><p>当 Nginx 镜像处于 <code>stopped</code>/<code>killed</code> 状态时，docker 的容器镜像会改变为 <code>unused</code> 状态。</p><p><strong>注</strong>：你可以看到这里所有的镜像的细节都非常清楚，比如内存使用，创建日期和时间。与命令行选项相比，从这里维护和监视容器将非常容易。</p><h4 id="networks" tabindex="-1">Networks <a class="header-anchor" href="#networks" aria-label="Permalink to “Networks”">​</a></h4><p>此选项用于网络操作。例如分配 IP 地址、创建子网、提供 IP 地址范围、访问控制（管理员和普通用户）。下面的窗口提供了各种可能选项的详细信息。根据你的需要，可以进一步去自行研究这些选项。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Network-1024x463.jpg" alt="Conatiner-Network-Portainer"></p><p>输入所有各种网络参数后，单击“create network”按钮即可创建网络。</p><h4 id="container" tabindex="-1">Container <a class="header-anchor" href="#container" aria-label="Permalink to “Container”">​</a></h4><p>此选项将提供容器状态。此列表将提供有关活动的和未运行的容器状态的详细信息。此输出类似于 docker ps 命令选项。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Containers-1024x364.jpg" alt="Containers-Status-Portainer"></p><p>在该窗口中，通过选中复选框并选择上述按钮可以根据需要控制容器停止和启动。一个例子如下：</p><p>例如，“CentOS”和“Ubuntu”容器都处于停止状态，现在可以通过选中复选框并点击“Start”按钮来启动它们。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/start_containers1-1024x432.jpg" alt="start_containers1"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/start_containers2-1024x307.jpg" alt="start_containers2"></p><p><strong>注意：</strong> 因为这两个都是 Linux 容器镜像，所以不会被启动。Portainer 尝试启动，但稍后又停止。试试启动“Nginx”，你会看到它变成了 <code>running</code> 状态。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/start_containers3-1024x435.jpg" alt="start_containers3"></p><h4 id="volume" tabindex="-1">Volume <a class="header-anchor" href="#volume" aria-label="Permalink to “Volume”">​</a></h4><p>参见本文章第一部分。</p><h3 id="portainer-中的设置选项" tabindex="-1">Portainer 中的设置选项 <a class="header-anchor" href="#portainer-中的设置选项" aria-label="Permalink to “Portainer 中的设置选项”">​</a></h3><p>到目前为止，我们已经在“Local”部分看到了基于 portainer 的各种特性。现在跳到所选 Docker 容器图像的“Settings”部分。</p><p>在 Portainer 的网页中单击“Settings”选项时，可以使用以下的配置选项：</p><h4 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to “Extensions”">​</a></h4><p>这是一个简单的 Portainer CE 订阅程序。详细信息和用途可以从附加的窗口中看到。这主要用于维护相应版本的许可证和订阅。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Extensions-1024x421.jpg" alt="Extensions"></p><h4 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to “Users”">​</a></h4><p>此选项用于添加具有或不具有管理权限的“用户”。下面的示例提供了相同的示例。</p><p>在本例中输入你的想好的用户名比如“shashi”和你选择的密码，然后点击下面的“Create User”按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/create_user-1024x350.jpg" alt="create_user_portainer"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/create_user2-1024x372.jpg" alt="create_user2_portainer"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Internal-user-Portainer-1024x257.jpg" alt="Internal-user-Portainer"></p><p>类似地，可以通过选中复选框并点击 “remove” 按钮来删除刚刚创建的用户“shashi”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/user_remove-1024x318.jpg" alt="user_remove_portainer"></p><h4 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to “Endpoints”">​</a></h4><p>此选项用于端点终端管理。终端可以添加和删除，如附加窗口中所示。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Endpoint-1024x349.jpg" alt="Endpoint-Portainer-GUI"></p><p>新终端“shashi”是使用如下所示的各种默认参数创建的，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Endpoint2-1024x379.jpg" alt="Endpoint2-Portainer-GUI"></p><p>类似地，可以通过单击复选框并单击移除按钮来移除此端点。</p><h4 id="registries" tabindex="-1">Registries <a class="header-anchor" href="#registries" aria-label="Permalink to “Registries”">​</a></h4><p>此选项用于注册管理。由于 docker hub 有各种镜像的注册，因此此功能可用于类似的目的。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Registry-1024x420.jpg" alt="Registry-Portainer-GUI"></p><p>使用默认选项就可以创建“shashi-registry”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Registry2-1024x409.jpg" alt="Registry2-Portainer-GUI"></p><p>同样，如果不需要了，就可以移除它。</p><h4 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h4><p>此选项用于设置以下各种选项，</p><ul><li>设置快照间隔</li><li>设置自定义徽标</li><li>创建外部模板</li><li>安全功能，如：为非管理员禁用和启用 bin 挂载，为非管理员禁用/启用权限，启用主机管理功能</li></ul><p>下面的屏幕截图显示了出于演示目的启用和禁用的一些选项。一旦全部完成点击“保存设置”按钮保存所有这些选项。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-GUI-Settings-1024x418.jpg" alt="Portainer-GUI-Settings"></p><p>现在点开“Authentication settings”就会弹出 LDAP、Internal 和 OAuth（extension）选项，如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Authentication-Portainer-GUI-Settings-1024x344.jpg" alt="Authentication-Portainer-GUI-Settings"></p><p>根据我们想要的环境安全特性级别，选择相应的选项。</p><p>以上就是本文的内容，我希望这些介绍 portainer 的文章能帮助你更有效地管理和监视容器。请分享你的反馈和意见。</p><hr>`,83)),e("p",null,[t[4]||(t[4]=a("via: ",-1)),s(n,{href:"https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-io-part-2/"},{default:i(()=>[...t[3]||(t[3]=[a("https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-io-part-2/",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=a("作者：",-1)),s(n,{href:"https://www.linuxtechi.com/author/shashidhar/"},{default:i(()=>[...t[5]||(t[5]=[a("Shashidhar Soppin",-1)])]),_:1}),t[10]||(t[10]=a(" 选题：",-1)),s(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[6]||(t[6]=[a("lujun9972",-1)])]),_:1}),t[11]||(t[11]=a(" 译者：",-1)),s(n,{href:"https://github.com/Chao-zhi"},{default:i(()=>[...t[7]||(t[7]=[a("Chao-zhi",-1)])]),_:1}),t[12]||(t[12]=a(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=a("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[a("LCTT",-1)])]),_:1}),t[16]||(t[16]=a(" 原创编译，",-1)),s(n,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[a("Linux中国",-1)])]),_:1}),t[17]||(t[17]=a(" 荣誉推出",-1))])])}const f=o(d,[["render",h]]);export{P as __pageData,f as default};
